/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { BulkEditDialogComponent, BulkEditDialogData } from './bulk-edit-dialog.component';

interface Item {
  name: string;
  count: number;
  active: boolean;
  status: string;
  owner: string;
  note: string;
}

const DATA: BulkEditDialogData<Item> = {
  title: 'Edit',
  count: 3,
  singular: 'item',
  plural: 'items',
  confirm: 'Apply',
  cancel: 'Cancel',
  fields: [
    { name: 'name', label: 'Name', type: 'text' },
    { name: 'count', label: 'Count', type: 'number', optional: true },
    { name: 'active', label: 'Active', type: 'boolean' },
    { name: 'status', label: 'Status', type: 'enum', options: [{ value: 'open', label: 'Open' }] },
    { name: 'owner', label: 'Owner', type: 'relation', optional: true },
    { name: 'note', label: 'Note', type: 'text', optional: true },
  ],
};

describe('BulkEditDialogComponent', () => {
  let component: BulkEditDialogComponent<Item>;
  let ref: { close: jasmine.Spy };

  beforeEach(() => {
    ref = { close: jasmine.createSpy('close') };
    TestBed.configureTestingModule({
      imports: [BulkEditDialogComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
      providers: [
        { provide: MAT_DIALOG_DATA, useValue: DATA },
        { provide: MatDialogRef, useValue: ref },
      ],
    });
    const fixture = TestBed.createComponent(BulkEditDialogComponent<Item>);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  afterEach(() => TestBed.resetTestingModule());

  it('starts every field off, with its first operation and an empty value', () => {
    expect(component.rows.map((row) => [row.enabled, row.operation, row.value])).toEqual([
      [false, 'replace', ''],
      [false, 'replace', 0],
      [false, 'setTrue', ''],
      [false, 'replace', ''],
      [false, 'setNull', ''],
      [false, 'replace', ''],
    ]);
    expect(component.hasChanges()).toBeFalse();
  });

  it('offers the operations of each type, with clear for the optional ones', () => {
    const names = (index: number) => component.operations(DATA.fields[index]).map((op) => op.value);

    expect(names(0)).toEqual(['replace', 'prefix', 'suffix']);
    expect(names(1)).toEqual(['replace', 'add', 'multiply', 'clear']);
    expect(names(2)).toEqual(['setTrue', 'setFalse']);
    expect(names(3)).toEqual(['replace']);
    expect(names(4)).toEqual(['setNull']);
    expect(names(5)).toEqual(['replace', 'prefix', 'suffix', 'clear']);
  });

  it('needs a value only for the operations that use one', () => {
    expect(component.requiresValue('prefix')).toBeTrue();
    expect(component.requiresValue('clear')).toBeFalse();
  });

  it('sends the changes of the enabled fields that are complete', () => {
    component.rows[0].enabled = true;
    component.rows[0].operation = 'prefix';
    component.rows[0].value = 'Dr. ';
    component.rows[1].enabled = true;
    component.rows[1].operation = 'clear';
    component.rows[2].enabled = true;
    component.rows[2].operation = 'setFalse';
    component.rows[3].enabled = true;
    component.rows[4].enabled = true;
    component.rows[5].enabled = true;
    component.rows[5].operation = 'setTrue' as any;

    expect(component.hasChanges()).toBeTrue();
    component.submit();

    expect(ref.close).toHaveBeenCalledWith([
      { field: 'name', operation: 'prefix', value: 'Dr. ' },
      { field: 'count', operation: 'clear', value: null },
      { field: 'active', operation: 'setFalse', value: false },
      { field: 'owner', operation: 'setNull', value: null },
      { field: 'note', operation: 'setTrue', value: true },
    ]);
  });
});
